async function main(): Promise<void> {
  const ws = new WritableStream();
  const w = new WritableStreamDefaultWriter(ws);
  console.log(typeof w.write, typeof w.close, typeof w.abort, typeof w.releaseLock, typeof w.closed, typeof w.ready);
  const rs = new ReadableStream();
  const r = new ReadableStreamDefaultReader(rs);
  console.log(typeof r.read, typeof r.cancel, typeof r.releaseLock, typeof r.closed);
  const te = new TextEncoderStream();
  const td = new TextDecoderStream();
  console.log(te.encoding, td.encoding, td.fatal, td.ignoreBOM, typeof te.readable, typeof td.writable);
  const cs = new CompressionStream("gzip");
  const ds = new DecompressionStream("gzip");
  console.log(typeof cs.readable, typeof cs.writable, typeof ds.readable, typeof ds.writable);
  const q = new CountQueuingStrategy({ highWaterMark: 3 });
  const b = new ByteLengthQueuingStrategy({ highWaterMark: 7 });
  console.log(q.highWaterMark, b.highWaterMark, typeof q.size, typeof b.size);
  const m = new PerformanceMark("x", { detail: 5 });
  console.log(m.name, m.entryType, m.detail, typeof m.startTime, m.duration, typeof m.toJSON);
  const o = new PerformanceObserver(() => {});
  console.log(typeof o.observe, typeof o.disconnect, typeof o.takeRecords);
}
